-- ============================================================================
-- Replace the mission bank with a curated set of GENERAL spontaneous quests,
-- organised by difficulty only (no themed categories). Seeded from the
-- product owner's examples and expanded — 25 per tier, 100 total.
-- ============================================================================

-- A single flat "general" category.
values ('general', 'כללי', 'משימות ספונטניות כלליות', 'sparkles', '#7C5CFF', 0)
on conflict (slug) do update set name = excluded.name, color = excluded.color;

-- Out with the old bank (cascades to old assignments/submissions — pre-launch).
delete from missions;

